  public static string Explain(int code){if(code>0&&code<65536)return "Код завершения программы; значение зависит от запущенной команды. Это не HRESULT Windows Update.";var description=ErrorReference31.Describe(code);if(description!=null)return description;switch(unchecked((uint)code)){case 0:return "Код HRESULT 0 означает отсутствие ошибки; итог операции определяется также её ResultCode.";
case 0x8007000E:return "Не удалось выделить память (E_OUTOFMEMORY). Проверьте RAM, лимит выделенной памяти и файл подкачки; код не означает повреждение пакета.";case 0x800705AA:return "Недостаточно системных ресурсов. Проверьте потребителей памяти и файл подкачки.";case 0x800705AF:return "Достигнут лимит выделенной памяти: файл подкачки слишком мал для операции.";case 0x80004005:return "Общий код E_FAIL. Причину определяют по тексту исключения и внутреннему HRESULT конкретного обновления.";case 0x80200059:return "BITS: передача запрещена политикой стоимости подключения. Проверьте лимитное подключение и политики BITS для этой задачи; очистка Download причину не устраняет.";
case 0x80070422:return "Служба отключена. Проверьте wuauserv и BITS, тип запуска и доменные политики; остановленная служба сама по себе не равна отключённой.";
case 0x80072F8F:return "Ошибка защищённого соединения: проверьте дату, время, сертификат и TLS, а также перехват HTTPS прокси.";
case 0x80244019:return "HTTP 404: ресурс WSUS не найден. Проверьте URL запроса, виртуальные каталоги IIS и наличие содержимого на WSUS.";
case 0x80070070:return "Недостаточно свободного места. Проверьте системный диск и каталог загрузки до повторной установки.";
case 0x80073712:return "Повреждено хранилище компонентов. Соберите актуальный CBS и выполните DISM ScanHealth; источник восстановления должен соответствовать ОС.";
case 0x80244010:return "Достигнут лимит обменов запросами с WSUS за один поиск. Это число обменов, а не обновлений. Повторите поиск без очистки кэша; при устойчивом повторении проверьте каталог и обслуживание WSUS.";
case 0x80240009:return "Другая операция Windows Update конфликтует с текущей. Проверьте фоновые задания; не очищайте кэш во время установки.";
case 0x80242014:return "WU_E_UH_POSTREBOOTSTILLPENDING: завершение обновления после перезагрузки ещё ожидается. Перезагрузите компьютер в согласованное время и затем проверьте результат; повторная установка и очистка кэша пока не требуются.";
case 0x80240016:return "Установка сейчас недопустима: выполняется другая установка либо требуется перезагрузка.";
case 0x80070020:return "Файл используется другим процессом (ERROR_SHARING_VIOLATION). Этот код не определяет путь или владельца блокировки.";
case 0x8007000D:return "Недопустимые данные при обработке пакета. Проверьте CBS; повторно скачайте пакет после завершения операций. Код не доказывает повреждение всего хранилища.";
case 0x80096010:return "Не прошла проверка цифровой подписи объекта. Проверьте пакет и источник WSUS; не отключайте проверку подписи.";
case 0x80070643:return "Общая ошибка установщика. Ищите внутренний код и журнал конкретного пакета; сброс Defender по одному этому коду не обоснован.";
case 0x800705B4:return "Истекло время ожидания операции. Проверьте движение загрузки, активный установщик и его журнал до остановки или очистки.";
