case 0x80070002:case 0x80070003:return "Файл или путь не найден. Сопоставьте путь и этап: временная ошибка может быть исправлена последующей попыткой.";
case 12002:case 0x80072EE2:return "Истекло время сетевого запроса. Проверьте источник восстановления/обновлений, доступ из SYSTEM, разрешение доступа в Kerio, прокси и политики. Конкретный сервер этим кодом не определяется.";case 0x80246002:return "Контрольная сумма скачанного обновления не совпала с ожидаемой. Файл отклонён Windows; установка этого обновления не выполнялась. Проверьте кэш клиента, содержимое WSUS и путь передачи.";case 0x80240034:return "Не удалось скачать обновление. Проверьте содержимое WSUS, сеть и кэш загрузок.";case 0x80070570:return "Файл или каталог повреждён и нечитаем. Возможны повреждение загрузки, хранилища компонентов или диска.";case 0xc0000005:return "Нарушение доступа к памяти процесса. По этому коду нельзя определить виновный компонент.";case 0x80240022:return "Сбой операции обновления. Общий код WUA не устанавливает причину; проверьте конкретное обновление и WindowsUpdate.log.";case 0x800F081F:return "Не найдены исходные файлы восстановления. Проверьте подходящий источник и индекс образа.";case 5:case 0x80070005:return "Отказано в доступе. Проверьте права и разрешения.";default:return "Проверенная расшифровка этого кода отсутствует. Сохраните системное сообщение и найдите описание по точному коду.";}}
